export type ScreenType = new (...args: never[]) => object;

export interface RouteEntry {
  readonly path: string;
  readonly screen: ScreenType;
}

export class RouteRegistry {
  private entries: RouteEntry[];

  constructor(initial: readonly RouteEntry[] = []) {
    const seen = new Set<string>();
    this.entries = initial.map((entry) => {
      this.validate(entry.path, entry.screen);
      if (seen.has(entry.path)) throw new RangeError("duplicate route path");
      seen.add(entry.path);
      return { path: entry.path, screen: entry.screen };
    });
  }

  private validate(path: string, screen: ScreenType): void {
    if (typeof path !== "string" || !path.startsWith("/") || /\s/.test(path)) {
      throw new TypeError("invalid route path");
    }
    if (typeof screen !== "function") throw new TypeError("invalid screen");
  }

  addOrReplace(path: string, screen: ScreenType): readonly RouteEntry[] {
    this.validate(path, screen);
    const index = this.entries.findIndex((entry) => entry.path === path);
    const next = this.entries.map((entry) => ({ ...entry }));
    if (index >= 0) next.push({ path, screen });
    else next.push({ path, screen });
    this.entries = next;
    return this.snapshot();
  }

  snapshot(): readonly RouteEntry[] {
    return this.entries.map((entry) => ({ ...entry }));
  }
}

