import { RouteRegistry } from './solution';
import type { RouteEntry, ScreenType } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsType(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}
function throwsRange(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

class HomeScreen {}
class NewHomeScreen {}
class DetailScreen {}

const initial: RouteEntry[] = [{ path: '/home', screen: HomeScreen }];
const registry = new RouteRegistry(initial);
(initial[0] as { path: string }).path = '/mutated';
initial.push({ path: '/extra', screen: DetailScreen });
let snap = registry.snapshot();
equal(snap.length, 1, 'constructor copies initial array');
equal(snap[0].path, '/home', 'constructor copies initial entries');
equal(snap[0].screen, HomeScreen as ScreenType, 'initial screen retained');

const replaced = registry.addOrReplace('/home', NewHomeScreen);
equal(replaced.length, 1, 'replacement does not append');
equal(replaced[0].path, '/home', 'replacement preserves position and path');
equal(replaced[0].screen, NewHomeScreen as ScreenType, 'replacement updates screen');
const appended = registry.addOrReplace('/detail', DetailScreen);
equal(appended.length, 2, 'new route appended');
equal(appended[0].path, '/home', 'existing position preserved');
equal(appended[1].path, '/detail', 'new route is last');

const snapA = registry.snapshot();
const snapB = registry.snapshot();
assert(snapA !== snapB, 'snapshot arrays are fresh');
assert(snapA[0] !== snapB[0] && snapA[1] !== snapB[1], 'snapshot entries are fresh');
assert(appended !== snapA && appended[0] !== snapA[0], 'add result is detached from later snapshots');
(snapA as RouteEntry[]).pop();
(snapB[0] as { path: string }).path = '/damaged';
const intact = registry.snapshot();
equal(intact.length, 2, 'mutating returned array does not alter registry');
equal(intact[0].path, '/home', 'mutating returned entry does not alter registry');

for (const path of ['', 'home', '/has space', '/tab\there']) {
  throwsType(() => registry.addOrReplace(path, HomeScreen), `invalid path rejected: ${path}`);
}
throwsType(() => registry.addOrReplace('/bad', 3 as unknown as ScreenType), 'non-function screen rejected');
throwsType(() => new RouteRegistry([{ path: 'bad', screen: HomeScreen }]), 'invalid initial path rejected');
throwsType(() => new RouteRegistry([{ path: '/bad', screen: null as unknown as ScreenType }]), 'invalid initial screen rejected');
throwsRange(() => new RouteRegistry([{ path: '/same', screen: HomeScreen }, { path: '/same', screen: DetailScreen }]), 'duplicate initial path rejected');

